select

from sai_model_config c
left join sai_model_provider p on p.id = c.provider_id



        and (
        c.model_key like concat('%', #{bo.keyword}, '%')
        or c.model_name like concat('%', #{bo.keyword}, '%')
        or c.description like concat('%', #{bo.keyword}, '%')
        )


        and c.model_key like concat('%', #{bo.modelKey}, '%')


        and c.model_name like concat('%', #{bo.modelName}, '%')


        and c.model_type = #{bo.modelType}


        and c.is_enabled = #{bo.isEnabled}


        and g.data_level_max = #{bo.dataLevelMax}


        and g.deployment_type = #{bo.deploymentType}


        and g.lifecycle_status = #{bo.lifecycleStatus}


        and g.status = #{bo.status}


order by c.is_default desc, c.model_type asc, c.id asc

select
from sai_model_config c left join sai_model_provider p on p.id = c.provider_id
where c.id = #{modelId}
